from typing import List

def process_times(n: int, a: int, T: List[int]) -> List[int]:
    current_time = 0
    finish_times = []
    for arrival_time in T:
        if arrival_time >= current_time:
            current_time = arrival_time + a
        else:
            current_time += a
        finish_times.append(current_time)
    return finish_times
